body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f4f4f4;
}

header {
    background-color: #333;
    color: #fff;
    padding: 10px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

header h1 {
    margin: 0;
}

header nav a {
    color: #fff;
    text-decoration: none;
    margin-left: 20px;
}

main {
    padding: 20px;
}

form {
    margin-bottom: 20px;
}

textarea {
    width: 100%;
    height: 100px;
    padding: 10px;
}

button {
    background-color: #333;
    color: #fff;
    border: none;
    padding: 10px 20px;
    cursor: pointer;
}

.note {
    background-color: #fff;
    padding: 10px;
    border: 1px solid #ccc;
    margin-bottom: 10px;
}

document.addEventListener('DOMContentLoaded', () => {
    const searchForm = document.getElementById('search-form');
    searchForm.addEventListener('submit', (event) => {
        const queryInput = searchForm.querySelector('input[name="query"]');
        if (!queryInput.value.trim()) {
            event.preventDefault();
            alert('Please enter a search query.');
        }
    });
});

from flask import Flask, request, jsonify, render_template, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///notes.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

# Database Model
class Note(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    content = db.Column(db.String(500), nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

db.create_all()

# Routes
@app.route('/')
def index():
    notes = Note.query.order_by(Note.created_at.desc()).all()
    return render_template('index.html', notes=notes)

@app.route('/create_note')
def create_note():
    return render_template('create_note.html')

@app.route('/create_note_action', methods=['POST'])
def create_note_action():
    content = request.form.get('content')
    if content:
        new_note = Note(content=content)
        db.session.add(new_note)
        db.session.commit()
    return redirect(url_for('index'))

@app.route('/notes', methods=['POST'])
def create_note_api():
    data = request.get_json()
    content = data.get('content', '')
    if content:
        new_note = Note(content=content)
        db.session.add(new_note)
        db.session.commit()
        return jsonify({'id': new_note.id, 'content': new_note.content, 'created_at': new_note.created_at}), 201
    return jsonify({'error': 'Content is required'}), 400

@app.route('/notes', methods=['GET'])
def get_notes_api():
    notes = Note.query.order_by(Note.created_at.desc()).all()
    return jsonify([{'id': note.id, 'content': note.content, 'created_at': note.created_at} for note in notes])

@app.route('/notes/search', methods=['GET'])
def search_notes_api():
    query = request.args.get('query', '')
    if query:
        results = Note.query.filter(Note.content.contains(query)).all()
        return jsonify([{'id': note.id, 'content': note.content, 'created_at': note.created_at} for note in results])
    return jsonify([])

@app.route('/search_notes', methods=['GET'])
def search_notes():
    query = request.args.get('query', '')
    results = []
    if query:
        results = Note.query.filter(Note.content.contains(query)).all()
    return render_template('search_results.html', results=results)

if __name__ == '__main__':
    app.run(debug=True)

import unittest
from flask import Flask, render_template
from flask_testing import TestCase

class TestFrontendComponents(TestCase):
    def create_app(self):
        app = Flask(__name__)
        app.config['TESTING'] = True

        @app.route('/')
        def index():
            return render_template('index.html', notes=[{'content': 'Sample Note', 'created_at': '2023-10-01'}])

        @app.route('/create_note')
        def create_note():
            return render_template('create_note.html')

        @app.route('/search_results')
        def search_results():
            return render_template('search_results.html', results=[{'content': 'Search Note', 'created_at': '2023-10-01'}])

        return app

    def test_index_page(self):
        response = self.client.get('/')
        self.assert200(response)
        self.assert_template_used('index.html')
        self.assertIn(b'Sample Note', response.data)

    def test_create_note_page(self):
        response = self.client.get('/create_note')
        self.assert200(response)
        self.assert_template_used('create_note.html')

    def test_search_results_page(self):
        response = self.client.get('/search_results')
        self.assert200(response)
        self.assert_template_used('search_results.html')
        self.assertIn(b'Search Note', response.data)

if __name__ == '__main__':
    unittest.main()

from flask import Blueprint, request, jsonify
from app.models import db, Note

routes = Blueprint('routes', __name__)

@routes.route('/notes', methods=['POST'])
def create_note():
    data = request.json
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'Invalid request'}), 400

    note = Note(title=data['title'], content=data['content'])
    db.session.add(note)
    db.session.commit()
    return jsonify({'id': note.id, 'title': note.title, 'content': note.content}), 201

@routes.route('/notes', methods=['GET'])
def get_notes():
    notes = Note.query.all()
    return jsonify([{'id': note.id, 'title': note.title, 'content': note.content} for note in notes]), 200

@routes.route('/notes/search', methods=['GET'])
def search_notes():
    query = request.args.get('q', '')
    if not query:
        return jsonify({'error': 'No search query provided'}), 400

    notes = Note.query.filter(Note.title.contains(query) | Note.content.contains(query)).all()
    return jsonify([{'id': note.id, 'title': note.title, 'content': note.content} for note in notes]), 200

